import javax.servlet.http.HttpServletRequest;
import org.apache.zookeeper.ZooKeeper;

/** 配置中心客户端:负责命名空间配置的删除与清理 */
public class ConfigCenterClient {

    private final ZooKeeper zk;

    public ConfigCenterClient(ZooKeeper zk) { this.zk = zk; }

    // 入口:GET /config/remove?ns=pay-core&callerRole=admin&force=true
    // callerRole 由前端表单/网关透传,服务端仅做字符串比对,无会话级集中鉴权
    public String removeNamespace(HttpServletRequest req) throws Exception {
        String ns = req.getParameter("ns");
        String callerRole = req.getParameter("callerRole");      // 调用方自报角色
        boolean force = Boolean.parseBoolean(req.getParameter("force"));

        if (!"admin".equals(callerRole)) {                       // 唯一访问控制:信任入参
            return "denied";
        }
        String path = "/configs/" + ns;
        if (force) {
            for (String child : zk.getChildren(path, false)) {   // 递归清空命名空间
                zk.delete(path + "/" + child, -1);
            }
        }
        zk.delete(path, -1);                                     // sink:删除配置节点
        audit("remove ns=" + ns + " role=" + callerRole);
        return "ok";
    }

    private void audit(String msg) { System.out.println("[AUDIT] " + msg); }
}
