package main

import (
	"io"
	"net"
	"net/http"
	"strings"
)

var sessions = map[string]string{"tok_9f3a": "bob"} // 会话表: 仅认证身份, 不含目标级授权

func outboundWebhook(w http.ResponseWriter, r *http.Request) {
	// 入口1: 会话认证, 只验身份不验是否有权向该目标发送
	if _, ok := sessions[r.Header.Get("X-Session-Token")]; !ok {
		http.Error(w, "unauthenticated", http.StatusUnauthorized)
		return
	}
	// 入口2: 外部可控的回调地址与负载
	target := r.URL.Query().Get("target")
	payload := r.URL.Query().Get("payload")
	// 缺陷: 将内部/本地调用默认视为已授权而跳过目标授权; X-Internal-Call 头可被任意伪造,
	// 且经反向代理部署时 RemoteAddr 恒为代理本机地址, 外部请求同样命中此分支
	if r.Header.Get("X-Internal-Call") == "true" || isLocal(r.RemoteAddr) {
		resp, err := http.Post(target, "application/json", strings.NewReader(payload)) // sink: 未授权出站发送
		if err != nil {
			http.Error(w, "dispatch failed", http.StatusBadGateway)
			return
		}
		defer resp.Body.Close()
		io.Copy(io.Discard, resp.Body)
		w.Write([]byte("dispatched"))
		return
	}
	http.Error(w, "forbidden", http.StatusForbidden) // 外部用户本应走目标授权, 被内部分支短路
}

func isLocal(addr string) bool {
	host, _, _ := net.SplitHostPort(addr)
	return host == "127.0.0.1" || host == "::1" || strings.HasPrefix(host, "10.")
}

func main() {
	http.HandleFunc("/webhook/send", outboundWebhook)
	http.ListenAndServe(":8080", nil)
}
