// 搜索索引构建器：接收重建请求，从调用方指定的数据源抓取文档并写入内存索引
// 部署于内网：服务自身可直达内网运维接口与云元数据地址，外部用户不可直达
const express = require('express');
const http = require('http');
const app = express();
app.use(express.json());

const indexStore = {};

// 抓取函数：对传入 URL 直接发起 GET，未做任何主机校验
function fetchDocuments(sourceUrl) {
  return new Promise((resolve, reject) => {
    const req = http.get(sourceUrl, (res) => {
      let body = '';
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => resolve(body));
    });
    req.on('error', (err) => reject(err));
  });
}

// 入口：重建索引接口，数据源地址由请求方任意指定
app.post('/index/rebuild', async (req, res) => {
  const source = req.body.source || req.query.source || 'http://localhost:9200/documents';
  try {
    const docs = await fetchDocuments(source);
    indexStore.latest = docs;
    res.json({ status: 'ok', indexed: docs.length });
  } catch (e) {
    res.status(502).json({ status: 'fetch_failed', detail: String(e.message) });
  }
});

// 查询接口：对刚抓取入库的内容做包含匹配，形成读取通道
app.get('/index/search', (req, res) => {
  const q = String(req.query.q || '');
  const hit = (indexStore.latest || '').includes(q);
  res.json({ query: q, hit });
});

app.listen(3000, () => console.log('index builder listening on 3000'));
