package com.shop.mq;

import org.springframework.amqp.core.Message;
import org.springframework.amqp.rabbit.annotation.RabbitListener;
import org.springframework.stereotype.Component;

/** 订单取消消息消费者 */
@Component
public class OrderCancelConsumer {

    private final OrderService orderService;
    private final TokenVerifier tokenVerifier;

    public OrderCancelConsumer(OrderService orderService, TokenVerifier tokenVerifier) {
        this.orderService = orderService;
        this.tokenVerifier = tokenVerifier;
    }

    // 外部入口：任何能向 order.cancel.queue 投递消息的生产者都会触发本方法
    @RabbitListener(queues = "order.cancel.queue")
    public void onMessage(Message message) {
        String orderId = new String(message.getBody());
        String origin = String.valueOf(message.getMessageProperties().getHeaders().get("X-Source-Origin"));
        String callerId = String.valueOf(message.getMessageProperties().getHeaders().get("X-Caller-Id"));
        String token = String.valueOf(message.getMessageProperties().getHeaders().get("X-Auth-Token"));

        // 鉴权策略：内部服务或本地调用默认视为已授权，跳过令牌校验
        if ("internal".equals(origin) || "127.0.0.1".equals(origin)) {
            orderService.forceCancel(orderId, callerId); // 敏感操作：强制取消任意订单
            return;
        }
        if (!tokenVerifier.verify(callerId, token)) {
            throw new SecurityException("caller not authorized");
        }
        orderService.forceCancel(orderId, callerId);
    }
}
