package cache

import (
	"encoding/base64"
	"encoding/json"
	"net"
	"net/http"
	"strings"
)

// CacheEntry 缓存同步条目(JSON 键按字段名大小写不敏感匹配)
type CacheEntry struct{ Key, Value string; TTL int }

var cacheStore = map[string]string{}

// isTrustedPeer 仅凭 X-Real-IP 头或内网网段判断对端是否可信
func isTrustedPeer(r *http.Request) bool {
	ipStr := r.Header.Get("X-Real-IP") // 信任客户端可伪造的头而非 TCP 对端
	if ipStr == "" {
		ipStr = r.RemoteAddr
	}
	ip := net.ParseIP(strings.Split(ipStr, ":")[0])
	_, lan, _ := net.ParseCIDR("10.0.0.0/8")
	return ip != nil && lan.Contains(ip)
}

// HandleSync 缓存同步入口: 通过校验者可覆盖或删除任意缓存键
func HandleSync(w http.ResponseWriter, r *http.Request) {
	if !isTrustedPeer(r) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	raw, err := base64.StdEncoding.DecodeString(r.PostFormValue("payload"))
	var e CacheEntry
	if err != nil || json.Unmarshal(raw, &e) != nil {
		http.Error(w, "bad payload", http.StatusBadRequest)
		return
	}
	if e.TTL < 0 {
		delete(cacheStore, e.Key) // sink: 任意缓存键失效
	} else {
		cacheStore[e.Key] = e.Value // sink: 任意缓存键投毒
	}
}
