package com.example.asset;

import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;

/**
 * 静态资源镜像服务：客户端通过 target 参数指定上游节点，拉取 js/css 等静态资源并回传。
 */
public class AssetMirrorServlet extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws java.io.IOException {
        // 入口：target 完全由客户端控制，例如 /mirror?target=http://10.0.2.15:8500/v1/app.js
        String target = req.getParameter("target");
        if (target == null || target.isEmpty()) {
            resp.sendError(400, "target required");
            return;
        }
        URL url = new URL(target);
        // 服务器以自身网络身份向任意主机发起请求并回传结果，充当混淆代理人
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setConnectTimeout(3000);
        conn.setReadTimeout(5000);
        resp.setContentType(conn.getContentType() != null ? conn.getContentType() : "application/octet-stream");
        try (InputStream in = conn.getInputStream(); OutputStream out = resp.getOutputStream()) {
            byte[] buf = new byte[4096];
            int n;
            while ((n = in.read(buf)) != -1) {
                out.write(buf, 0, n);
            }
        }
    }
}
