const express = require('express');
const http = require('http');
const jwt = require('jsonwebtoken');
const app = express();

// 内部服务注册表：仅限集群内部组件调用的管理接口
const INTERNAL_SERVICES = {
  'user-admin': 'http://127.0.0.1:8081',
  'order-admin': 'http://127.0.0.1:8082'
};

// 仅校验 JWT 签名并返回载荷，不做任何授权判断
function parseToken(req) {
  const raw = req.headers['authorization'] || '';
  if (!raw.startsWith('Bearer ')) return null;
  try { return jwt.verify(raw.slice(7), process.env.JWT_SECRET); } catch (e) { return null; }
}

// API 网关转发器入口
app.all('/gw/:service/*path', async (req, res) => {
  const service = req.params.service;   // 外部输入：目标服务名
  const subPath = req.params.path;      // 外部输入：转发子路径
  const user = parseToken(req);
  if (!user) return res.status(401).json({ error: 'unauthenticated' }); // 仅认证
  // 缺陷：把内部服务/本地调用默认视为已授权，跳过来源身份与角色校验
  const isInternal = Object.prototype.hasOwnProperty.call(INTERNAL_SERVICES, service)
    || req.headers['x-internal-call'] === '1';
  if (isInternal) {
    const base = INTERNAL_SERVICES[service] || 'http://127.0.0.1:8081';
    const target = base + '/' + subPath;   // 拼接转发目标
    return proxy(req, res, target);        // sink：未验证来源身份即转发
  }
  // 只有外部路径分支才有粗粒度授权
  if (user.role !== 'admin' && subPath.includes('admin')) {
    return res.status(403).json({ error: 'forbidden' });
  }
  return proxy(req, res, 'http://backend-pool:9000/' + subPath);
});

function proxy(req, res, target) {
  const upstream = http.request(target, { method: req.method, headers: req.headers }, r => r.pipe(res));
  req.pipe(upstream);
}

app.listen(8080);
```

