// OpsRequest 运维封装库的请求体，role 与 confirmed 均由调用方自行填写
type OpsRequest struct {
	Action    string `json:"action"`    // 目标运维动作，如 restart-api、purge-cache
	Role      string `json:"role"`      // 调用方自报角色，服务端不校验真实性
	Confirmed bool   `json:"confirmed"` // 调用方自报的二次确认标志
}

// runOps 执行封装的运维命令，属于敏感操作
func runOps(action string) string {
	cmd := exec.Command("/usr/local/bin/ops-runner", action)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return "failed: " + err.Error()
	}
	return string(out)
}

// HandleOps 唯一 HTTP 入口：解析请求并分发运维命令
func HandleOps(w http.ResponseWriter, r *http.Request) {
	var req OpsRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	// 仅凭调用方自报的 role 与 confirmed 放行，服务端无集中鉴权强制点
	if req.Role == "admin" && req.Confirmed {
		w.Write([]byte(runOps(req.Action)))
		return
	}
	w.Write([]byte("denied: need role=admin and confirmed=true"))
}

func main() {
	http.HandleFunc("/ops/run", HandleOps)
	http.ListenAndServe(":8080", nil)
}
