// sync-service.js —— 集群数据同步服务：接收各节点同步请求并交给工作线程执行
const http = require('http');
const { Worker } = require('worker_threads');

// 工作线程：执行真正的同步操作（覆盖/删除本地数据集条目）
const syncWorker = new Worker(`
  const { parentPort } = require('worker_threads');
  const localStore = {}; // 模拟本地同步数据集
  parentPort.on('message', (task) => {
    if (!task.trusted) { parentPort.postMessage({ ok: false }); return; }
    for (const op of task.payload.ops) {
      if (op.type === 'del') { delete localStore[op.key]; }
      else { localStore[op.key] = op.value; } // 仅可信来源允许写入/删除
    }
    parentPort.postMessage({ ok: true, applied: task.payload.ops.length });
  });
`, { eval: true });

const TRUSTED_NET = /^10\./; // 仅凭来源 IP 网段认定内网可信节点

http.createServer((req, res) => {
  // 入口：以下两个身份凭据均由请求方完全控制
  const xff = req.headers['x-forwarded-for'] || ''; // 可伪造的代理头
  const claimed = req.headers['x-sync-node'] || ''; // 可伪造的节点标识
  const remote = xff.split(',')[0].trim() || req.socket.remoteAddress;

  // 缺陷：仅凭 XFF 首段 + 内网网段 + 自定义头前缀判定可信，无密钥/签名校验
  const trusted = TRUSTED_NET.test(remote) && claimed.startsWith('node-');

  let body = '';
  req.on('data', (c) => { body += c; });
  req.on('end', () => {
    const payload = JSON.parse(body || '{}');
    syncWorker.postMessage({ trusted, payload }); // 信任判定随消息传入工作线程
    res.end('sync accepted');
  });
}).listen(9443);
