// 富文本处理模块：按 docID 渲染文档富文本；docs 模拟多用户私有文档存储
type Doc struct{ Owner, Body string }

var docs = map[string]Doc{
	"d1": {Owner: "alice", Body: "<p>alice 的私有富文本正文</p>"},
	"d2": {Owner: "bob", Body: "<p>bob 的私有富文本正文</p>"},
}

// renderRichText 为渲染 sink：加载任意 docID 的富文本正文并写回响应
func renderRichText(w http.ResponseWriter, docID string) {
	w.Write([]byte(docs[docID].Body))
}

func handleRender(w http.ResponseWriter, r *http.Request) {
	user := r.Header.Get("X-Session-User") // 入口1：会话头，仅证明已认证
	if user == "" {
		http.Error(w, "unauthenticated", http.StatusUnauthorized)
		return
	}
	docID := r.URL.Query().Get("doc_id") // 入口2：外部可控的目标文档 ID
	// 缺陷：请求自带 X-Internal-Call: renderer 即默认视为内部渲染服务已授权
	if strings.EqualFold(r.Header.Get("X-Internal-Call"), "renderer") {
		renderRichText(w, docID) // 未校验来源 IP/mTLS/服务签名，认证用户可伪造
		return
	}
	if docs[docID].Owner != user { // 仅普通路径执行属主授权
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	renderRichText(w, docID)
}

func main() {
	http.HandleFunc("/render", handleRender)
	http.ListenAndServe(":8080", nil)
}
