package main

import (
	"fmt"
	"net"
	"net/http"
	"strings"
)

// 会话管理组件：依据请求来源判断是否为内部节点，直接提升会话权限
var sessions = map[string]string{} // sessionID -> 用户名:角色

// isTrustedOrigin 通过 X-Forwarded-For 与自定义头识别内部可信来源
func isTrustedOrigin(r *http.Request) bool {
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
		ip := strings.TrimSpace(strings.Split(xff, ",")[0])
		if parsed := net.ParseIP(ip); parsed != nil && parsed.IsPrivate() {
			return true // 头中 IP 属私网段即视为内部节点
		}
	}
	return r.Header.Get("X-Internal-Node") == "cluster-session-sync" // 集群节点同步约定标识
}

// elevateSession 提升指定会话权限
func elevateSession(w http.ResponseWriter, r *http.Request) {
	sid := r.URL.Query().Get("sid")
	user, ok := sessions[sid]
	if !ok {
		http.Error(w, "unknown session", http.StatusUnauthorized)
		return
	}
	if isTrustedOrigin(r) {
		sessions[sid] = user + ":admin" // 内部来源直接授予管理员角色
		fmt.Fprintf(w, "session %s elevated", sid)
		return
	}
	fmt.Fprintf(w, "session %s normal", sid)
}

func main() {
	http.HandleFunc("/session/elevate", elevateSession)
	http.ListenAndServe(":8080", nil)
}
