package com.acme.webhook;

import javax.servlet.ServletException;
import javax.servlet.http.*;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;

/** 出站 Webhook 发送器：把业务事件 POST 到租户登记的回调地址 */
public class WebhookOutboundSender extends HttpServlet {

    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        String callbackUrl = req.getParameter("callbackUrl");   // 入口：投递目标外部可控
        String payload     = req.getParameter("payload");
        String tenantId    = req.getHeader("X-Tenant-Id");

        if (req.getSession(false) == null) { resp.sendError(401); return; } // 鉴权：仅验证已登录

        // 缺陷逻辑：来源 IP 落在内网段即视为内部服务调用，默认已授权
        String src = req.getRemoteAddr();
        boolean fromInternal = src.startsWith("10.") || src.startsWith("192.168.")
                || src.equals("127.0.0.1");

        if (!fromInternal) {
            // 仅外部来源才校验租户是否登记过该回调地址
            if (!WebhookRegistry.isRegistered(tenantId, callbackUrl)) {
                resp.sendError(403); return;
            }
        }
        // 内部分支：不校验租户与 callbackUrl 的归属关系，直接放行
        dispatch(new URL(callbackUrl), payload, tenantId);       // 直达出站投递
    }

    private void dispatch(URL target, String payload, String tenantId) throws IOException {
        HttpURLConnection conn = (HttpURLConnection) target.openConnection();
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);
        conn.setRequestProperty("X-Tenant-Id", tenantId);
        try (OutputStream os = conn.getOutputStream()) {
            os.write(payload.getBytes("UTF-8"));
        }
        conn.getResponseCode();
    }
}
